contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // msg.sender for calls to c will be this contract (the deployer of C), which is the owner
    // We take inputs: a target receiver and an amount to attempt to transfer from c.
    function run(address receiver, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Record contract balance before owner's call
        uint256 balBefore = address(c).balance;

        // As owner (this contract deployed c), calling sendTo should succeed and reduce c's balance by exactly amount
        bool ownerReverted;
        try c.sendTo(receiver, amount) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        uint256 balAfterOwner = address(c).balance;

        // Now simulate a non-owner call: we need an external caller. We'll perform a low-level call from this contract
        // to c.sendTo but using a different caller is not possible inside the single transaction since msg.sender would still be this contract.
        // Instead we can detect that any attempt where msg.sender != owner should revert; we create a new calldata and call via address(c).call
        // but msg.sender remains this contract. To emulate a non-owner, we assert that if ownerReverted==false then the balance decreased by amount;
        // and if ownerReverted==true then balance unchanged. This enforces correct behavior for the owner path and that no funds are lost on revert.

        assert(
            // If owner's call did not revert then contract balance decreased by exactly amount (or amount couldn't be transferred due to insufficient balance causing revert)
            (!ownerReverted && balBefore == balAfterOwner + amount) ||
            // If owner's call reverted then balance must be unchanged
            (ownerReverted && balBefore == balAfterOwner)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take receiver and amount as inputs. This function is payable only to allow
    // forwarding Ether into this test contract before calling c.sendTo.
    function run(address payable receiver, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // record balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeReceiver = address(receiver).balance;

        // attempt call as owner: the InvMutTest contract deployed c, so it is c's owner
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterReceiver = address(receiver).balance;

        // General rule:
        // If the call did NOT revert then
        //  - c's balance decreased by exactly amount (i.e., afterC = beforeC - amount)
        //  - receiver's balance increased by at least amount (afterReceiver >= beforeReceiver + amount)
        // If the call reverted then balances are unchanged for both c and receiver.
        assert( (!reverted && afterC + amount == beforeC && afterReceiver >= beforeReceiver + amount) ||
                (reverted && afterC == beforeC && afterReceiver == beforeReceiver) );
    }

    // allow this contract to receive Ether so tests can fund it
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // receiver and amount are inputs; function payable so test can be funded if needed
    function run(address payable receiver, uint256 amount) public payable {
        // require the contract under test has at least `amount` so transfer can succeed if permitted
        require(address(c).balance >= amount);

        // Call sendTo and detect whether it reverted
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // GENERAL RULE: if C has sufficient balance for the requested amount, the owner (this contract)
