        assert(!reverted);
    }

    // allow this contract to receive Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // caller is the owner (this contract deployed c). Provide receiver and amount; payable so test can be funded.
    function run(address payable receiver, uint256 amount) public payable {
        // ensure this test contract (owner) has enough balance to fund C if needed and to cover any forwarded value
        require(address(this).balance >= 0);

        // record C's balance before the call
        uint256 before = address(c).balance;

        // make the call and record whether it reverted
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // GENERAL RULE: if the call did not revert, C's balance must have decreased by exactly `amount`.
        // If it reverted, no further guarantee is required by this property.
        assert(reverted || after + amount == before);
    }

    receive() external payable {}
}

