contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Ensure the caller (this contract) is owner of C. Take receiver and amount as inputs.
    function run(address payable receiver, uint256 amount) public payable {
        // Precondition: amount must not exceed C's current balance so transfer can be funded.
        uint256 balBefore = address(c).balance;
        require(amount <= balBefore);

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // GENERAL RULE: under the precondition, the owner's call does not revert.
        assert(!reverted);
    }

    receive() external payable { }
